import{_ as o,o as r,c as s,a2 as t}from"./chunks/framework.CTx8wfac.js";const h=JSON.parse('{"title":"Basic Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/basic-concepts.md","filePath":"guide/basic-concepts.md"}'),a={name:"guide/basic-concepts.md"};function d(n,e,c,i,l,g){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="basic-concepts" tabindex="-1">Basic Concepts <a class="header-anchor" href="#basic-concepts" aria-label="Permalink to &quot;Basic Concepts&quot;">​</a></h1><p>These are the <strong>foundations</strong>—routing, validation, responses, errors—that everything else builds on. The surface is already <strong>broad</strong> (see <a href="/banana-universe/guide/advanced-concepts.html">Advanced concepts</a>); this page grounds you in the core. Public API: <code>packages/bananajs/src/index.ts</code>.</p><h2 id="controllers-and-routes" tabindex="-1">Controllers and routes <a class="header-anchor" href="#controllers-and-routes" aria-label="Permalink to &quot;Controllers and routes&quot;">​</a></h2><ul><li><strong><code>@Controller(segment)</code></strong> — class decorator; <strong>slash-free</strong> base segment (e.g. <code>&#39;users&#39;</code>, <code>&#39;&#39;</code> for root). The framework joins segments when mounting routes.</li><li><strong><code>@Get</code> / <code>@Post</code> / <code>@Put</code> / <code>@Patch</code> / <code>@Delete</code></strong> — method decorators; signature <code>(path = &#39;&#39;, ...middlewares?)</code>. Path segments are also <strong>slash-free</strong> (e.g. <code>&#39;list&#39;</code>, <code>&#39;:id&#39;</code>, <code>&#39;&#39;</code> for the controller root).</li></ul><p>Controllers should extend <strong><code>BaseController</code></strong> for <strong><code>this.ok</code></strong> / <strong><code>this.error</code></strong> helpers.</p><p>Controllers are passed to <strong><code>BananaApp</code></strong> as <strong>constructors</strong> (not instances). The framework reads metadata at startup and wires Express.</p><h2 id="validation-body-query-params-headers" tabindex="-1">Validation: body, query, params, headers <a class="header-anchor" href="#validation-body-query-params-headers" aria-label="Permalink to &quot;Validation: body, query, params, headers&quot;">​</a></h2><p>These decorators wrap the handler and run <strong><code>schema.safeParse</code></strong> on the matching request slice:</p><ol><li>On failure — throw <strong><code>BadRequestError</code></strong></li><li>On success — assign <strong><code>result.data</code></strong> to <code>req</code> and call your method</li></ol><table tabindex="0"><thead><tr><th>Decorator</th><th>Validates</th></tr></thead><tbody><tr><td><code>@Body(schema)</code></td><td><code>req.body</code></td></tr><tr><td><code>@Query(schema)</code></td><td><code>req.query</code></td></tr><tr><td><code>@Params(schema)</code></td><td><code>req.params</code></td></tr><tr><td><code>@Headers(schema)</code></td><td><code>req.headers</code> (as consumed by Zod)</td></tr></tbody></table><p>Use <strong>Zod</strong> (<code>z.object</code>, <code>z.coerce.number()</code>, etc.). OpenAPI can infer request bodies from <code>@Body</code> schemas when <strong><code>@ApiBody</code></strong> is omitted.</p><h2 id="success-responses" tabindex="-1">Success responses <a class="header-anchor" href="#success-responses" aria-label="Permalink to &quot;Success responses&quot;">​</a></h2><p><strong><code>SuccessResponse&lt;T&gt;</code></strong> carries a message and <strong><code>data: T</code></strong>. <strong><code>BaseController.ok(res, message, data)</code></strong> delegates to <strong><code>SuccessResponse</code></strong>.</p><p>Shape is consistent across endpoints (<code>statusCode</code>, <code>status</code>, <code>message</code>, <code>data</code>).</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Throw subclasses of <strong><code>ApiError</code></strong> (e.g. <strong><code>NotFoundError</code></strong>, <strong><code>BadRequestError</code></strong>, <strong><code>UnauthorisedError</code></strong> — UK spelling in the framework). Use <strong><code>ErrorMiddleware</code></strong> (or <strong><code>createErrorMiddleware(logger?)</code></strong>) as the Express error handler so <strong><code>ApiError.handle</code></strong> maps types to typed HTTP responses.</p><p>Unknown errors are treated as internal failures; in <strong>production</strong>, internal error messages are not leaked.</p><h2 id="app-bootstrap" tabindex="-1">App bootstrap <a class="header-anchor" href="#app-bootstrap" aria-label="Permalink to &quot;App bootstrap&quot;">​</a></h2><ul><li><strong><code>BananaApp.create(controllers, options)</code></strong> — use when <strong>plugins</strong> need async <code>register</code> / <code>onReady</code> (e.g. TypeORM).</li><li><strong><code>createBananaApplication(controllers, { ...options, port?, onListening? })</code></strong> — optional <strong><code>listen</code></strong> in one call.</li></ul>',19)])])}const u=o(a,[["render",d]]);export{h as __pageData,u as default};
